import time
import numpy as np
from treehfd import XGBTreeHFD


def _run(model, Xfit, Xpred, depth):
    hfd = XGBTreeHFD(model)
    kw = dict(interaction_order=2, verbose=False)
    if depth is not None:
        hfd.fit(Xfit, depth_variable=depth, **kw)
    else:
        hfd.fit(Xfit, **kw)
    y_main, y_o2 = hfd.predict(Xpred, verbose=False)
    comps = {(j,): np.asarray(y_main[:, j], dtype=float)
             for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        a, b = int(a), int(b)
        if a > b:
            a, b = b, a
        comps[(a, b)] = np.asarray(y_o2[:, k], dtype=float)
    return float(hfd.eta0), comps


def _mse(model, eta0, comps, X):
    pred = np.full(X.shape[0], eta0)
    for v in comps.values():
        pred = pred + v
    return float(np.mean((model.predict(X) - pred) ** 2))


def decompose(model, X_train, X_test):
    X_train = np.asarray(X_train, dtype=float)
    n = X_train.shape[0]
    rng = np.random.RandomState(0)
    idx = rng.permutation(n)
    tr = idx[:min(1000, max(10, int(0.7 * n)))]
    ho = idx[int(0.7 * n):][:500]
    if len(ho) < 10 or len(tr) < 10:
        tr = ho = idx[:min(n, 500)]
    t0 = time.time()
    best, best_d = np.inf, None
    for d in [2, 3, 4]:
        if time.time() - t0 > 60:
            break
        try:
            e, c = _run(model, X_train[tr], X_train[ho], d)
            m = _mse(model, e, c, X_train[ho])
        except Exception:
            continue
        if np.isfinite(m) and m < best:
            best, best_d = m, d
    if best_d is None:
        best_d = 2
    try:
        return _run(model, X_train, X_test, best_d)
    except Exception:
        hfd = XGBTreeHFD(model)
        hfd.fit(X_train, interaction_order=2, verbose=False)
        y_main, y_o2 = hfd.predict(X_test, verbose=False)
        comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
        for k, (a, b) in enumerate(hfd.interaction_list):
            comps[(int(a), int(b))] = y_o2[:, k]
        return float(hfd.eta0), comps
